cd /workspace && ls -la output output/archive inputs; cat inputs/turn.json; sha256sum output/archive/close-1.xlsx inputs/source.xlsx; python - <<'EOF'
from openpyxl import load_workbook
wb=load_workbook('inputs/source.xlsx')
print(wb.sheetnames)
ws=wb['Events']; print(ws.max_row)
for r in ws.iter_rows(min_row=93,values_only=True): print(r)
for n in ['Products','Aliases','Contracts','OperatorNotes']:
    print('==',n,wb[n].max_row, wb[n].merged_cells.ranges, wb[n].freeze_panes)
for r in wb['Lines'].iter_rows(min_row=146,values_only=True): print(r)
for r in wb['OperatorNotes'].iter_rows(values_only=True): print(r)
for row in wb['OperatorNotes'].iter_rows():
    for c in row:
        if c.comment or c.fill.fill_type: print(c.coordinate,c.fill.fgColor.rgb,c.comment and c.comment.text)
a=load_workbook('output/archive/close-1.xlsx',data_only=True)
for r in a['Summary'].iter_rows(values_only=True): print(r)
EOF

cd /workspace && python refresh.py --source inputs/source.xlsx --as-of 2026-04-15 --previous output/archive/close-1.xlsx --output output/settlement.xlsx; echo rc=$?; sha256sum output/archive/close-1.xlsx; python - <<'EOF'
import json
r=json.load(open('output/reconciliation.json'))
print({k:v for k,v in r.items() if k not in('summary','ineligible_event_ids')})
for s in r['summary']: print(s)
from openpyxl import load_workbook
d={x[0]:x for x in load_workbook('output/settlement.xlsx')['Detail'].iter_rows(min_row=2,values_only=True)}
for k in ['MOVING','MOVING-RETURN','CANCELLED','REOPENED','ALIAS-EDGE','EARLY-CREDIT','FRACTION-APRIL','R0036','R0056','R0120','R0140','P0027','P0006','P0016']: print(k,d.get(k))
EOF

